-- PR359 isolated PostgreSQL 17 synthetic test.
-- The temp payment fixture comes from the REAL 20261103131104 migration CHECK
-- in the same psql session, generated by scripts/pr359-financial-shadow-preflight.mjs.
-- This test is NOT a Production-derived Shadow restore or full financial migration run.
BEGIN;

INSERT INTO pr359_payment_split_fixture
(fixture_group,payment_purpose,amount,invoice_applied_amount,subscriber_credit_amount)
VALUES
 ('baseline','invoice_collection',210,210,0),
 ('baseline','invoice_collection',250,250,0),
 ('baseline','invoice_collection',300,300,0),
 ('baseline','invoice_collection',200,200,0),
 ('baseline','invoice_collection',300,300,0),
 ('synthetic','invoice_collection_with_credit',110,85,25),
 ('synthetic','subscriber_credit',75,0,75),
 ('synthetic','security_deposit',50,0,0),
 ('synthetic','security_deposit_refund',50,0,0);

DO $$
DECLARE n integer; cash numeric;
BEGIN
 SELECT count(*),sum(amount) INTO n,cash FROM pr359_payment_split_fixture WHERE fixture_group='baseline';
 IF n<>5 OR cash<>1260 THEN
   RAISE EXCEPTION 'BASELINE_MISMATCH: %, %',n,cash;
 END IF;
 SELECT sum(invoice_applied_amount) INTO cash
 FROM pr359_payment_split_fixture WHERE fixture_group='synthetic';
 IF cash<>85 THEN RAISE EXCEPTION 'INVOICE_COLLECTION_OVERSTATED: %',cash; END IF;
 SELECT sum(subscriber_credit_amount) INTO cash
 FROM pr359_payment_split_fixture WHERE fixture_group='synthetic';
 IF cash<>100 THEN RAISE EXCEPTION 'CREDIT_SPLIT_INCORRECT: %',cash; END IF;
END $$;

-- Invalid amounts are rejected by the source-migration CHECK (not a copied predicate).
DO $$
BEGIN
 BEGIN
  INSERT INTO pr359_payment_split_fixture VALUES ('bad','invoice_collection',100,90,10);
  RAISE EXCEPTION 'FALSE_ACCEPTANCE_INVOICE_COLLECTION';
 EXCEPTION WHEN check_violation THEN NULL;
 END;
 BEGIN
  INSERT INTO pr359_payment_split_fixture VALUES ('bad','invoice_collection_with_credit',100,100,0);
  RAISE EXCEPTION 'FALSE_ACCEPTANCE_MIXED_CREDIT';
 EXCEPTION WHEN check_violation THEN NULL;
 END;
 BEGIN
  INSERT INTO pr359_payment_split_fixture VALUES ('bad','subscriber_credit',100,100,0);
  RAISE EXCEPTION 'FALSE_ACCEPTANCE_SUBSCRIBER_CREDIT';
 EXCEPTION WHEN check_violation THEN NULL;
 END;
 BEGIN
  INSERT INTO pr359_payment_split_fixture VALUES ('bad','security_deposit_refund',100,100,0);
  RAISE EXCEPTION 'FALSE_ACCEPTANCE_DEPOSIT_REFUND';
 EXCEPTION WHEN check_violation THEN NULL;
 END;
END $$;

-- Synthetic legacy backfill simulation tests selection and idempotency.
-- The full historic source migration has further dependencies and is not run here.
CREATE TEMP TABLE legacy_payments (
 id bigint PRIMARY KEY,
 invoice_id bigint,
 status text NOT NULL,
 payment_purpose text NOT NULL,
 amount numeric(14,2) NOT NULL,
 invoice_applied_amount numeric(14,2) NOT NULL,
 subscriber_credit_amount numeric(14,2) NOT NULL
);
INSERT INTO legacy_payments VALUES
 (1,42,'completed','invoice_collection',120,120,0),
 (2,NULL,'completed','invoice_collection',55,55,0),
 (3,NULL,'pending','invoice_collection',45,0,0);
UPDATE legacy_payments
SET payment_purpose='subscriber_credit',
    invoice_applied_amount=0,
    subscriber_credit_amount=round(amount,2)
WHERE invoice_id IS NULL AND status='completed'
  AND coalesce(payment_purpose,'invoice_collection')='invoice_collection'
  AND amount>0;

DO $$
BEGIN
 IF (SELECT count(*) FROM legacy_payments WHERE payment_purpose='subscriber_credit')<>1
 THEN RAISE EXCEPTION 'LEGACY_SCOPE_MISMATCH'; END IF;
 IF (SELECT invoice_applied_amount FROM legacy_payments WHERE id=1)<>120
 THEN RAISE EXCEPTION 'LINKED_CASH_RECLASSIFIED'; END IF;
 IF (SELECT subscriber_credit_amount FROM legacy_payments WHERE id=2)<>55
 THEN RAISE EXCEPTION 'CREDIT_LIABILITY_LOST'; END IF;
 IF (SELECT payment_purpose FROM legacy_payments WHERE id=3)<>'invoice_collection'
 THEN RAISE EXCEPTION 'PENDING_PAYMENT_RECLASSIFIED'; END IF;
END $$;
DO $$
DECLARE affected integer;
BEGIN
 UPDATE legacy_payments
 SET payment_purpose='subscriber_credit'
 WHERE invoice_id IS NULL AND status='completed'
 AND coalesce(payment_purpose,'invoice_collection')='invoice_collection'
 AND amount>0;
 GET DIAGNOSTICS affected = ROW_COUNT;
 IF affected<>0 THEN RAISE EXCEPTION 'RECLASSIFICATION_NOT_IDEMPOTENT: %',affected; END IF;
END $$;
ROLLBACK;
